"use client";

import React, { useState } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import remarkMath from "remark-math";
import rehypeKatex from "rehype-katex";
import {
  Target,
  BookOpen,
  Scale,
  Sparkles,
  Layers,
  Globe,
  HelpCircle,
  Copy,
  Check,
  CheckCircle2,
  AlertCircle,
  Zap,
} from "lucide-react";

/**
 * Pre-normalizes mathematical notation and delimiters generated by LLMs:
 * 1. Converts \[ ... \] to $$ ... $$
 * 2. Converts \( ... \) to $ ... $
 * 3. Normalizes accidental double-dollar typos at line ends (e.g. $x_0 = 2.5$$ -> $x_0 = 2.5$)
 * 4. Ensures math blocks have necessary spacing for remark-math parser
 */
export function normalizeMathContent(text: string): string {
  if (!text) return "";
  let clean = text;

  // 1. Convert LaTeX display delimiters \[ ... \] to $$ ... $$
  clean = clean.replace(/\\\[([\s\S]*?)\\\]/g, (_, eq) => `\n$$\n${eq.trim()}\n$$\n`);

  // 2. Convert LaTeX inline delimiters \( ... \) to $ ... $
  clean = clean.replace(/\\\(([\s\S]*?)\\\)/g, (_, eq) => `$${eq.trim()}$`);

  // 3. Fix trailing double-dollar typo on inline math: e.g. "$x_0 = 2.5$$" -> "$x_0 = 2.5$"
  clean = clean.replace(/([^\$])\$\$([^\$]|$)/g, "$1$$$2");

  // 4. Clean up any accidental 3+ consecutive dollar signs
  clean = clean.replace(/\${3,}/g, "$$");

  return clean;
}

interface CodeBlockProps {
  code: string;
  language?: string;
}

const CodeBlock: React.FC<CodeBlockProps> = ({ code, language }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div
      className="my-3 rounded-2xl bg-midnight-ink text-spectral-white overflow-hidden border border-stormy-slate/40 shadow-sm"
      dir="ltr"
    >
      <div className="flex items-center justify-between px-4 py-2 bg-black/40 border-b border-stormy-slate/30 text-[10px] font-mono text-stormy-slate font-bold">
        <span className="text-eerie-sage uppercase tracking-wider">
          {language ? language : "CODE / PSEUDOCODE"}
        </span>
        <button
          type="button"
          onClick={handleCopy}
          className="flex items-center gap-1.5 text-spectral-white/80 hover:text-spectral-white transition-all py-0.5 px-2 rounded hover:bg-white/10"
        >
          {copied ? (
            <>
              <Check className="w-3.5 h-3.5 text-eerie-sage" />
              <span className="text-eerie-sage text-xs">Copied</span>
            </>
          ) : (
            <>
              <Copy className="w-3.5 h-3.5" />
              <span className="text-xs">Copy</span>
            </>
          )}
        </button>
      </div>
      <pre className="p-4 overflow-x-auto font-mono text-xs leading-relaxed text-spectral-white/95">
        <code>{code}</code>
      </pre>
    </div>
  );
};

interface MarkdownRendererProps {
  content: string;
  dir?: "rtl" | "ltr";
  className?: string;
}

export const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({
  content,
  dir = "rtl",
  className = "",
}) => {
  const normalized = normalizeMathContent(content);

  return (
    <div className={`prose-container ${className}`} dir={dir}>
      <ReactMarkdown
        remarkPlugins={[remarkGfm, remarkMath]}
        rehypePlugins={[rehypeKatex]}
        components={{
          table: ({ node, ...props }) => (
            <div className="prose-table-container">
              <table className="prose-table" {...props} />
            </div>
          ),
          th: ({ node, ...props }) => <th {...props} />,
          td: ({ node, ...props }) => <td {...props} />,
          code: ({ node, className: codeClass, children, ...props }: any) => {
            const match = /language-(\w+)/.exec(codeClass || "");
            const rawText = String(children);
            const isInline = !match && !rawText.includes("\n");

            if (isInline) {
              return (
                <code
                  dir="ltr"
                  className="inline-block font-mono text-[11px] sm:text-xs font-bold px-1.5 py-0.5 rounded-md bg-midnight-ink/10 text-midnight-ink border border-stormy-slate/25 mx-1 align-baseline"
                  {...props}
                >
                  {children}
                </code>
              );
            }

            const codeBody = rawText.replace(/\n$/, "");
            return <CodeBlock code={codeBody} language={match ? match[1] : ""} />;
          },
          p: ({ node, ...props }) => (
            <p className="my-2 leading-relaxed text-midnight-ink text-xs sm:text-sm font-arabic" {...props} />
          ),
          strong: ({ node, ...props }) => (
            <strong className="font-extrabold text-midnight-ink mx-0.5" {...props} />
          ),
          ul: ({ node, ...props }) => (
            <ul className="space-y-1.5 my-2 pr-4 list-disc list-outside marker:text-eerie-sage text-xs sm:text-sm" {...props} />
          ),
          ol: ({ node, ...props }) => (
            <ol className="space-y-1.5 my-2 pr-4 list-decimal list-outside marker:text-midnight-ink marker:font-bold text-xs sm:text-sm" {...props} />
          ),
          li: ({ node, ...props }) => (
            <li className="leading-relaxed text-midnight-ink font-arabic pl-1" {...props} />
          ),
          h1: ({ node, ...props }) => (
            <h1 className="text-base sm:text-lg font-black text-midnight-ink my-3 border-b border-stormy-slate/20 pb-1.5" {...props} />
          ),
          h2: ({ node, ...props }) => (
            <h2 className="text-sm sm:text-base font-extrabold text-midnight-ink my-2.5" {...props} />
          ),
          h3: ({ node, ...props }) => (
            <h3 className="text-xs sm:text-sm font-bold text-midnight-ink my-2" {...props} />
          ),
          blockquote: ({ node, ...props }) => (
            <blockquote className="border-r-4 border-eerie-sage bg-eerie-sage/10 p-3 rounded-lg my-2 text-xs sm:text-sm italic" {...props} />
          ),
        }}
      >
        {normalized}
      </ReactMarkdown>
    </div>
  );
};

interface TutorContentFormatterProps {
  content: string;
}

export const TutorContentFormatter: React.FC<TutorContentFormatterProps> = ({ content }) => {
  if (!content) return null;

  // Check if content has the Phase 1 Bento Onboarding Points
  const hasPhase1Points =
    content.includes("1. المطلوب") ||
    (content.includes("المطلوب") && content.includes("Objective")) ||
    content.includes("2. شرح الدرس") ||
    content.includes("Phase 1: Deep Onboarding");

  // Check if content contains an Active Challenge block [Stage X / 3]
  const hasStageBanner = content.includes("[Stage") && content.includes("/ 3]");

  // If this is a regular markdown message without special bento structures, render cleanly
  if (!hasPhase1Points && !hasStageBanner) {
    return (
      <div className="space-y-3 text-midnight-ink font-arabic selection:bg-eerie-sage/30">
        <MarkdownRenderer content={content} />
      </div>
    );
  }

  /**
   * Block Parser: Group structured content into semantic Bento cards,
   * while rendering the body of each card strictly with KaTeX-enabled MarkdownRenderer.
   */
  const renderFormattedSections = () => {
    const rawLines = content.split("\n");
    const elements: React.ReactNode[] = [];
    let i = 0;

    while (i < rawLines.length) {
      const line = rawLines[i].trim();

      if (!line) {
        i++;
        continue;
      }

      // --- A. Phase 1 Header ---
      if (line.includes("Phase 1") || line.includes("Deep Onboarding")) {
        elements.push(
          <div
            key={`p1-hdr-${i}`}
            className="my-3 pb-3 border-b-2 border-midnight-ink flex items-center justify-between"
          >
            <div className="flex items-center gap-2.5">
              <div className="w-7 h-7 rounded-lg bg-midnight-ink text-spectral-white flex items-center justify-center shadow-xs">
                <Sparkles className="w-4 h-4 text-eerie-sage" />
              </div>
              <div>
                <h3 className="text-sm sm:text-base font-black text-midnight-ink font-arabic">
                  التأسيس المعمق (Phase 1: Deep Onboarding)
                </h3>
                <p className="text-[10px] text-stormy-slate font-medium">
                  شرح المفاهيم الستة الأساسية المعتمدة في الكورس قبل بدء التحديات
                </p>
              </div>
            </div>
            <span className="text-[10px] uppercase font-bold tracking-wider px-2.5 py-1 rounded-full bg-midnight-ink text-spectral-white shadow-2xs">
              6 Points
            </span>
          </div>
        );
        i++;
        continue;
      }

      // Normalize line for bulletproof regex and keyword matching
      const normLine = line.replace(/[\*\#\_]/g, "").trim();

      // --- B. The 6 Onboarding Points ---
      const isPoint1 = normLine.includes("1. المطلوب") || (normLine.includes("المطلوب") && normLine.includes("Objective"));
      const isPoint2 = normLine.includes("2. شرح الدرس") || normLine.includes("شرح الدرس والمفهوم") || normLine.includes("Core Lesson");
      const isPoint3 = normLine.includes("3. القواعد") || normLine.includes("القواعد المستعملة") || normLine.includes("Active & Future Rules");
      const isPoint4 = normLine.includes("4. مثال تمهيدي") || normLine.includes("مثال تمهيدي بسيط") || normLine.includes("Simple Warm-up");
      const isPoint5 = normLine.includes("5. مثال يحاكي") || normLine.includes("مثال يحاكي السلسلة") || normLine.includes("مثال يحاكي السلس") || normLine.includes("Source-Level");
      const isPoint6 = normLine.includes("6. مثال تشبيهي") || normLine.includes("مثال تشبيهي من الواقع") || normLine.includes("Real-Life Analogy");

      if (isPoint1 || isPoint2 || isPoint3 || isPoint4 || isPoint5 || isPoint6) {
        let icon = <Target className="w-4 h-4 text-eerie-sage shrink-0" />;
        let title = "1. المطلوب (The Objective)";
        let subtitle = "الهدف التعليمي الأساسي للتمرين";

        if (isPoint2) {
          icon = <BookOpen className="w-4 h-4 text-eerie-sage shrink-0" />;
          title = "2. شرح الدرس والمفهوم (Core Lesson Explanation)";
          subtitle = "المفاهيم النظرية وآلية العمل الرياضية/البرمجية";
        } else if (isPoint3) {
          icon = <Scale className="w-4 h-4 text-eerie-sage shrink-0" />;
          title = "3. القواعد المستعملة والمستقبلية (Active & Future Rules)";
          subtitle = "القواعد الحالية لتجاوز التمرين + قواعد متقدمة للامتحانات القادمة";
        } else if (isPoint4) {
          icon = <Sparkles className="w-4 h-4 text-eerie-sage shrink-0" />;
          title = "4. مثال تمهيدي بسيط (Simple Warm-up Example)";
          subtitle = "تطبيق مصغر لتثبيت المفهوم الأساسي بدون تعقيد";
        } else if (isPoint5) {
          icon = <Layers className="w-4 h-4 text-eerie-sage shrink-0" />;
          title = "5. مثال يحاكي السلسلة (Source-Level Example)";
          subtitle = "تطبيق كامل خطوة بخطوة بنفس مستوى تمارين الكورس والجداول والعمليات الحسابية";
        } else if (isPoint6) {
          icon = <Globe className="w-4 h-4 text-eerie-sage shrink-0" />;
          title = "6. مثال تشبيهي من الواقع (Real-Life Analogy)";
          subtitle = "ربط المفهوم البرمجي بمثال حقيقي ملموس لا يُنسى";
        }

        // Gather all markdown body lines for this point until the next point or stage
        const bodyLines: string[] = [];
        const cleanHeaderRest = line.replace(/^[\*\#\_\s]*\d+\.?[^\:\)]*[\:\)][\*\#\_\s]*/, "").trim();
        if (cleanHeaderRest) {
          bodyLines.push(cleanHeaderRest);
        }

        i++;
        while (i < rawLines.length) {
          const nextL = rawLines[i];
          const nextTrimmed = nextL.trim();
          const nextNorm = nextTrimmed.replace(/[\*\#\_]/g, "").trim();

          if (
            nextTrimmed.startsWith("# Phase 1") ||
            nextNorm.includes("[Stage") ||
            nextNorm.includes("1. المطلوب") ||
            (nextNorm.includes("المطلوب") && nextNorm.includes("Objective")) ||
            nextNorm.includes("2. شرح الدرس") ||
            nextNorm.includes("3. القواعد") ||
            nextNorm.includes("4. مثال تمهيدي") ||
            nextNorm.includes("5. مثال يحاكي") ||
            nextNorm.includes("6. مثال تشبيهي")
          ) {
            break;
          }

          bodyLines.push(nextL);
          i++;
        }

        const pointBody = bodyLines.join("\n").trim();

        elements.push(
          <div
            key={`point-card-${i}`}
            className="my-3 rounded-2xl bg-white border border-stormy-slate/20 shadow-xs p-4 sm:p-5 transition-all hover:border-stormy-slate/35"
          >
            <div className="flex items-center gap-2.5 pb-2.5 mb-2.5 border-b border-stormy-slate/15">
              <div className="w-7 h-7 rounded-xl bg-midnight-ink text-spectral-white flex items-center justify-center shrink-0 shadow-2xs">
                {icon}
              </div>
              <div>
                <h4 className="text-xs sm:text-sm font-extrabold text-midnight-ink font-arabic">
                  {title}
                </h4>
                <p className="text-[10px] text-stormy-slate font-medium">{subtitle}</p>
              </div>
            </div>

            <div className="space-y-2 text-xs sm:text-sm leading-relaxed text-midnight-ink font-arabic pr-1">
              <MarkdownRenderer content={pointBody} />
            </div>
          </div>
        );
        continue;
      }

      // --- C. Active Stage Challenge Banner & Questions ---
      if (line.includes("[Stage") && line.includes("/ 3]")) {
        const stageHeader = line.replace(/[\*#\[\]]/g, "").trim();

        let questionEn = "";
        let briefAr = "";

        i++;
        while (i < rawLines.length) {
          const nextL = rawLines[i].trim();
          if (
            nextL.startsWith("#") ||
            nextL.includes("[Stage") ||
            nextL.includes("1. المطلوب") ||
            nextL.includes("2. شرح الدرس")
          ) {
            break;
          }

          if (nextL.includes("Question (English):")) {
            questionEn = nextL.replace(/(\*\*Question \(English\):\*\*|Question \(English\):)/, "").trim();
          } else if (nextL.includes("المطلوب باختصار:")) {
            briefAr = nextL.replace(/(\*\*المطلوب باختصار:\*\*|المطلوب باختصار:)/, "").trim();
          } else if (!questionEn) {
            questionEn = nextL;
          } else if (questionEn && !briefAr) {
            briefAr = nextL;
          }
          i++;
        }

        elements.push(
          <div
            key={`stage-challenge-${i}`}
            className="my-4 rounded-3xl bg-midnight-ink text-spectral-white p-5 sm:p-6 shadow-md border border-midnight-ink transition-all"
          >
            {/* Header */}
            <div className="flex items-center justify-between pb-3.5 mb-3.5 border-b border-stormy-slate/30">
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-2xl bg-eerie-sage text-midnight-ink flex items-center justify-center font-black text-base shadow-sm">
                  <Zap className="w-5 h-5 text-midnight-ink" />
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <h4 className="text-xs sm:text-sm font-black text-spectral-white font-mono tracking-tight">
                      {stageHeader}
                    </h4>
                    <span className="px-2 py-0.5 rounded-full bg-eerie-sage/20 text-eerie-sage text-[10px] font-bold border border-eerie-sage/30">
                      Mastery Gate (9/10)
                    </span>
                  </div>
                  <p className="text-[10px] text-stormy-slate font-arabic">
                    أجب عن هذا التحدي للانتقال إلى المرحلة التالية
                  </p>
                </div>
              </div>
              <span className="px-2.5 py-1 rounded-full bg-white/10 text-spectral-white text-[10px] font-bold">
                Active Challenge
              </span>
            </div>

            {/* English Question Box (Strictly LTR with KaTeX) */}
            {questionEn && (
              <div
                className="rounded-2xl bg-white text-midnight-ink p-4 border border-white/20 shadow-xs mb-3"
                dir="ltr"
              >
                <div className="flex items-center justify-between mb-1.5">
                  <span className="text-[10px] font-mono font-bold uppercase tracking-wider text-stormy-slate flex items-center gap-1">
                    <HelpCircle className="w-3.5 h-3.5 text-midnight-ink" />
                    <span>QUESTION (ENGLISH):</span>
                  </span>
                  <span className="text-[9px] font-mono text-stormy-slate/70">Solve clearly</span>
                </div>
                <div className="text-xs sm:text-sm font-bold text-midnight-ink font-sans leading-relaxed">
                  <MarkdownRenderer content={questionEn} dir="ltr" />
                </div>
              </div>
            )}

            {/* Arabic Brief Box (Strictly RTL with KaTeX) */}
            {briefAr && (
              <div
                className="rounded-2xl bg-eerie-sage/15 border border-eerie-sage/40 p-3.5 text-spectral-white"
                dir="rtl"
              >
                <div className="flex items-center gap-1.5 text-eerie-sage font-extrabold text-xs mb-1">
                  <span>📌 المطلوب باختصار:</span>
                </div>
                <div className="text-xs sm:text-sm text-spectral-white/95 font-arabic leading-relaxed font-medium">
                  <MarkdownRenderer content={briefAr} dir="rtl" />
                </div>
              </div>
            )}
          </div>
        );
        continue;
      }

      // --- D. Strengths & Weaknesses Feedback ---
      if (line.includes("نقاط القوة") || line.includes("Strengths")) {
        elements.push(
          <div
            key={`strength-${i}`}
            className="p-3 rounded-2xl bg-emerald-50 border border-emerald-200 text-xs sm:text-sm text-emerald-900 my-2 flex items-start gap-2.5 font-arabic"
          >
            <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0 mt-0.5" />
            <div className="flex-1 leading-relaxed">
              <MarkdownRenderer content={line} />
            </div>
          </div>
        );
        i++;
        continue;
      }

      if (line.includes("نقاط الضعف") || line.includes("Weaknesses")) {
        elements.push(
          <div
            key={`weakness-${i}`}
            className="p-3 rounded-2xl bg-amber-50 border border-amber-200 text-xs sm:text-sm text-amber-900 my-2 flex items-start gap-2.5 font-arabic"
          >
            <AlertCircle className="w-4 h-4 text-amber-600 shrink-0 mt-0.5" />
            <div className="flex-1 leading-relaxed">
              <MarkdownRenderer content={line} />
            </div>
          </div>
        );
        i++;
        continue;
      }

      // --- E. Standard Paragraph or Code block ---
      // Collect any consecutive lines that belong to standard prose
      const proseLines: string[] = [line];
      i++;
      while (i < rawLines.length) {
        const nextL = rawLines[i];
        const nextTrimmed = nextL.trim();
        const nextNorm = nextTrimmed.replace(/[\*\#\_]/g, "").trim();

        if (
          nextTrimmed.startsWith("# Phase 1") ||
          nextNorm.includes("[Stage") ||
          nextNorm.includes("1. المطلوب") ||
          (nextNorm.includes("المطلوب") && nextNorm.includes("Objective")) ||
          nextNorm.includes("2. شرح الدرس") ||
          nextNorm.includes("3. القواعد") ||
          nextNorm.includes("4. مثال تمهيدي") ||
          nextNorm.includes("5. مثال يحاكي") ||
          nextNorm.includes("6. مثال تشبيهي") ||
          nextNorm.includes("نقاط القوة") ||
          nextNorm.includes("نقاط الضعف")
        ) {
          break;
        }

        proseLines.push(nextL);
        i++;
      }

      elements.push(
        <div key={`prose-${i}`} className="my-2">
          <MarkdownRenderer content={proseLines.join("\n")} />
        </div>
      );
    }

    return elements;
  };

  return (
    <div className="space-y-3 text-midnight-ink font-arabic selection:bg-eerie-sage/30">
      {renderFormattedSections()}
    </div>
  );
};
